        ctx.fill();
        ctx.strokeStyle = withAlpha(theme.textColor, 0.28);
        ctx.lineWidth = 1;
        ctx.setLineDash([]);
        ctx.stroke();
        ctx.fillStyle = theme.textColor;
        ctx.textAlign = "left";
        ctx.textBaseline = "middle";
        ctx.fillText(label, x0 + 6, chipY + chipH / 2 + 0.5);
